+        line-height: 1;
+        letter-spacing: -0.055em;
+      }
+
+      .intro {
+        max-width: 34rem;
+        margin: 0;
+        color: var(--muted);
+        font-size: 1.05rem;
+        line-height: 1.6;
+      }
+
+      form {
+        padding: 1rem 2rem 2rem;
+      }
+
+      .form-field {
+        margin: 0 0 1.5rem;
+        padding: 1.25rem;
+        border: 1px solid var(--border);
+        border-radius: 1.1rem;
+        background: linear-gradient(180deg, rgba(23, 32, 51, 0.96), rgba(16, 24, 39, 0.96));
+      }
+
+      fieldset {
+        min-width: 0;
+        margin: 0;
+        padding: 0;
+        border: 0;
+      }
+
+      legend {
+        margin-bottom: 1rem;
+        color: var(--text);
+        font-size: 1.2rem;
+        font-weight: 750;
+      }
+
+      .radio-options {
+        display: grid;
+        gap: 0.85rem;
+      }
+
+      .radio-option {
+        display: flex;
+        align-items: center;
+        gap: 0.8rem;
+        min-width: 0;
+        padding: 1rem;
+        border: 1px solid var(--border);
+        border-radius: 0.95rem;
+        background: var(--surface);
+        color: var(--text);
+        cursor: pointer;
+        transition:
+          border-color 160ms ease,
+          background-color 160ms ease,
+          transform 160ms ease;
+      }
+
+      .radio-option:hover {
+        border-color: var(--accent);
+        background: var(--surface-strong);
+        transform: translateY(-1px);
+      }
+
+      .radio-option input {
+        width: 1.2rem;
+        height: 1.2rem;
+        margin: 0;
+        accent-color: var(--accent);
+        flex: 0 0 auto;
+      }
+
+      .radio-option span {
+        overflow-wrap: anywhere;
+      }
+
+      .radio-option:has(input:checked) {
+        border-color: var(--accent-strong);
+        background: #1b2a45;
+      }
+
+      .radio-option:has(input:focus-visible) {
+        outline: 3px solid var(--focus);
+        outline-offset: 3px;
+      }
+
+      .submit-button {
+        width: 100%;
+        border: 0;
+        border-radius: 999px;
+        padding: 0.95rem 1.25rem;
+        background: linear-gradient(135deg, #8fb7ff, #d5b4ff);
+        color: #08111f;
+        font: inherit;
+        font-weight: 800;
+        cursor: pointer;
+        box-shadow: 0 1rem 2rem rgba(143, 183, 255, 0.2);
+        transition:
+          filter 160ms ease,
+          transform 160ms ease;
+      }
+
+      .submit-button:hover {
+        filter: brightness(1.08);
+        transform: translateY(-1px);
+      }
+
+      .submit-button:focus-visible {
+        outline: 3px solid var(--focus);
+        outline-offset: 4px;
+      }
+
+      @media (max-width: 30rem) {
+        body {
+          padding: 1rem;
+        }
+
+        header,
+        form {
+          padding-inline: 1rem;
+        }
+      }
+
+      @media (forced-colors: active) {
+        .preference-card,
+        .form-field,
+        .radio-option {
+          border-color: ButtonBorder;
+        }
+
+        .submit-button {
+          border: 1px solid ButtonBorder;
+          background: ButtonFace;
+          color: ButtonText;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <div id="root"></div>
+
+    <script>
+      const notificationChoices = ["Email", "SMS", "Push Notifications"];
+
+      function RadioOption({ label, value, name, required }) {
+        return `
+          <label class="radio-option">
+            <input type="radio" name="${name}" value="${value}" ${required ? "required" : ""}>
+            <span>${label}</span>
+          </label>
+        `;
+      }
+
+      function NotificationQuestion() {
+        return `
+          <div class="form-field">
+            <fieldset>
+              <legend>How do you prefer to receive notifications?</legend>
