+                ${notificationChoices
+                  .map((choice) =>
+                    RadioOption({
+                      label: choice,
+                      value: choice.toLowerCase().replaceAll(" ", "-"),
+                      name: "notification-preference",
+                      required: true
+                    })
+                  )
+                  .join("")}
+              </div>
+            </fieldset>
+          </div>
+        `;
+      }
+
+      function PreferenceForm() {
+        return `
+          <form>
+            ${NotificationQuestion()}
+            <button class="submit-button" type="submit">Submit preference</button>
+          </form>
+        `;
+      }
+
+      function App() {
+        return `
+          <main class="app-shell">
+            <section class="preference-card" aria-labelledby="page-title">
+              <header>
+                <h1 id="page-title">Notification Preferences</h1>
+                <p class="intro">
+                  Choose the single channel you want us to use for important updates.
+                </p>
+              </header>
+              ${PreferenceForm()}
+            </section>
+          </main>
+        `;
+      }
+
+      document.querySelector("#root").innerHTML = App();
+    </script>
+  </body>
+</html>
*** End Patch
